/* ============ VIRAIS E MEMES ============ */
virais: [
  { n: 'Drop bears', t: 'Lendas', d: 'O "coala carnívoro" que cai das árvores em cima dos turistas. Não existe, mas todo australiano jura que sim. Dica: passe Vegemite atrás da orelha.', wk: 'pt.wikipedia.org/wiki/Drop_bear' },
  { n: 'A Guerra dos Emus', t: 'Lendas', y: '1932', d: 'O exército australiano usou metralhadoras contra 20 mil emus que destruíam plantações em WA. Os emus venceram. É história real.', w: 'Emu War', wk: 'pt.wikipedia.org/wiki/Guerra_aos_Emus' },
  { n: '"Tudo na Austrália quer te matar"', t: 'Lendas', d: 'O meme eterno sobre aranhas, cobras, águas-vivas e crocodilos. Na prática, morre-se muito mais afogado ou no trânsito.', wk: 'pt.wikipedia.org/wiki/Fauna_da_Austr%C3%A1lia' },
  { n: 'Shoey', t: 'Comportamento', d: 'Beber cerveja (ou champanhe) no próprio sapato. Daniel Ricciardo levou o ritual para o pódio da Fórmula 1.', w: 'Shoey', wk: 'en.wikipedia.org/wiki/Drinking_from_shoes' },
  { n: 'Democracy sausage', t: 'Comportamento', d: 'O cachorro-quente vendido nos locais de votação. Foi eleita palavra do ano em 2016, e tem até site que mapeia onde tem.', w: 'Democracy sausage', wk: 'en.wikipedia.org/wiki/Democracy_sausage' },
  { n: 'Cebola em cima ou embaixo?', t: 'Comportamento', y: '2018', d: 'A Bunnings mandou colocar a cebola embaixo da linguiça "por segurança" (ela escorregava). Virou debate nacional.', wk: 'en.wikipedia.org/wiki/Democracy_sausage' },
  { n: 'Bin chicken', t: 'Comportamento', d: 'O apelido do íbis-branco, ave que vive revirando lixeiras em Sydney e Brisbane. Virou mascote não oficial.', w: 'Australian white ibis', wk: 'pt.wikipedia.org/wiki/%C3%8Dbis-branco-australiano' },
  { n: '"Throw another shrimp on the barbie"', t: 'Frases', y: '1984', d: 'Paul Hogan num comercial de turismo para os EUA. Ironia: australiano não fala "shrimp", fala "prawn".', wk: 'en.wikipedia.org/wiki/Shrimp_on_the_barbie' },
  { n: '"That\'s not a knife"', t: 'Frases', y: '1986', d: '"Isso não é uma faca. ISSO é uma faca." A cena de Crocodilo Dundee é imitada até hoje.', wk: 'pt.wikipedia.org/wiki/Crocodilo_Dundee' },
  { n: '"Tell him he\'s dreamin\'"', t: 'Frases', y: '1997', d: 'Do filme The Castle. Resposta padrão para qualquer proposta absurda (como um preço alto demais).', wk: 'en.wikipedia.org/wiki/The_Castle_(1997_Australian_film)' },
  { n: '"Crikey!"', t: 'Frases', d: 'A interjeição de Steve Irwin, sinônimo de entusiasmo australiano no mundo todo.', wk: 'pt.wikipedia.org/wiki/Steve_Irwin' },
  { n: '"Yeah, nah"', t: 'Frases', d: 'Quer dizer "não". "Nah, yeah" quer dizer "sim". E "yeah, nah, yeah"... boa sorte.', wk: 'en.wikipedia.org/wiki/Australian_English_vocabulary' },
  { n: 'Bob Katter e os crocodilos', t: 'Internet', y: '2017', d: 'Perguntado sobre o casamento igualitário, o deputado disse "let there be a thousand blossoms bloom" e emendou que "a cada três meses uma pessoa é feita em pedaços por um crocodilo no norte de Queensland". A mudança de assunto virou meme e até caneca.', w: 'Bob Katter', wk: 'en.wikipedia.org/wiki/Bob_Katter' },
  { n: '“Don’t you dare say that!”', t: 'Internet', y: '2025', d: 'De novo Bob Katter: em agosto de 2025, numa coletiva de apoio a protestos contra a imigração, um repórter citou sua origem libanesa e o deputado sacudiu o punho na cara dele: "Não diga isso, porque isso me irrita, e eu soco quem diz isso". O vídeo viralizou.', w: 'Bob Katter', wk: 'en.wikipedia.org/wiki/Bob_Katter' },
  { n: 'Peggy and Molly', t: 'Internet', y: '2020', ig: 'peggyandmolly', d: 'A amizade entre Peggy, uma staffy, e Molly, um filhote de magpie resgatado na Gold Coast durante a pandemia, conquistou centenas de milhares de seguidores. Em 2024, Molly foi levada pelo governo por falta de licença e voltou para casa depois de uma campanha dos fãs.' },
  { n: '"Democracy manifest"', t: 'Internet', y: '1991', d: 'Jack Karlson sendo preso em Brisbane depois de uma "suculenta refeição chinesa" e gritando "Gentlemen, this is democracy manifest!". O vídeo viralizou em 2009 e virou lenda.', w: 'Jack Karlson', wk: 'pt.wikipedia.org/wiki/Democracy_Manifest' },
  { n: '"Just waiting for a mate"', t: 'Internet', d: 'No reality policial Highway Patrol, um rapaz parado pela polícia responde a todas as perguntas com "I\'m just waiting for a mate". Um clássico da internet australiana.', w: 'Just waiting for a mate', wk: 'en.wikipedia.org/wiki/Just_waiting_for_a_mate' },
  { n: 'Corey Worthington', t: 'Internet', y: '2008', d: 'Adolescente de Melbourne que anunciou uma festa no MySpace, juntou 500 pessoas e deu entrevista na TV sem tirar os óculos amarelos. Se recusou a pedir desculpas, e o país não esqueceu.', w: 'Corey Worthington party', wk: '' },
  { n: '"Doing a Bradbury"', t: 'Frases', y: '2002', d: 'Steven Bradbury vinha em último na patinação de velocidade das Olimpíadas de Inverno quando todos os rivais caíram, e ele levou o ouro. "Fazer um Bradbury" é ganhar quando ninguém esperava.', w: 'Steven Bradbury', wk: 'pt.wikipedia.org/wiki/Steven_Bradbury' },
  { n: 'Raygun', t: 'Internet', y: '2024', d: 'A professora Rachael Gunn competiu no breaking nas Olimpíadas de Paris com o "passo do canguru", tirou zero e virou um dos memes do ano.', w: 'Rachael Gunn', wk: 'en.wikipedia.org/wiki/Rachael_Gunn' },
  { n: 'Dumb Ways to Die', t: 'Internet', y: '2012', d: 'Campanha de segurança do metrô de Melbourne com bichinhos morrendo de jeitos bobos. Viralizou e ganhou prêmios em Cannes.', wk: 'pt.wikipedia.org/wiki/Dumb_Ways_to_Die' },
  { n: 'Os cães de Johnny Depp', t: 'Internet', y: '2015', d: 'O ministro Barnaby Joyce ameaçou sacrificar os cães do ator, trazidos sem quarentena. Depp e Amber Heard gravaram um vídeo de desculpas que virou meme.', w: 'Pistol and Boo', wk: 'pt.wikipedia.org/wiki/Johnny_Depp' },
  { n: 'A cebola de Tony Abbott', t: 'Internet', y: '2015', d: 'O então primeiro-ministro mordeu uma cebola crua inteira, com casca, numa visita a uma fazenda. Nunca foi esquecido.', w: 'Tony Abbott', wk: 'pt.wikipedia.org/wiki/Tony_Abbott' },
  { n: 'Big Things', t: 'Internet', d: 'Mais de 150 esculturas gigantes à beira da estrada: Big Banana, Big Pineapple, Big Prawn, Big Merino... Selfie obrigatória.', w: 'Australia\'s big things', wk: 'en.wikipedia.org/wiki/Big_things_(Australia)' },
  { n: 'Bluey', t: 'Internet', d: 'Cenas do desenho viraram memes de pais no mundo todo, e o episódio "Keepy Uppy" é usado para explicar a vida adulta.', wk: 'pt.wikipedia.org/wiki/Bluey_(s%C3%A9rie_de_televis%C3%A3o)' }
],

